import {
    Table,
    GenericColumn,
    TableNameColumn,
    BooleanColumn,
    StringColumn,
    FieldListColumn,
    ReferenceColumn,
    GuidColumn,
    ListColumn,
    ScriptColumn,
    ChoiceColumn,
    IntegerColumn,
    ConditionsColumn,
} from '@servicenow/sdk/core'

export const sysevent_email_action = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_labels: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sysrule',
    label: 'Notification',
    name: 'sysevent_email_action',
    schema: {
        event_name: GenericColumn({
            columnType: 'sysevent_name',
            label: 'Event name',
        }),
        collection: TableNameColumn({
            attributes: {
                allow_public: true,
            },
            label: 'Table',
        }),
        event_parm_1: BooleanColumn({
            label: [
                {
                    hint: 'The first event parameter contains a recipient, either a user sys_id, group sys_id or an email address, who should receive this notification',
                    label: 'Event parm 1 contains recipient',
                    plural: 'Event parm 1 contains recipients',
                    language: 'en',
                },
            ],
        }),
        subject: StringColumn({
            label: 'Subject',
            maxLength: 100,
        }),
        importance: StringColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Importance/Priority flag for the email',
                    label: 'Importance',
                    plural: 'Importances',
                    language: 'en',
                },
            ],
        }),
        from: StringColumn({
            label: [
                {
                    hint: 'Email address you want to appear in the From field',
                    label: 'From',
                    plural: 'Froms',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        recipient_fields: FieldListColumn({
            dependent: 'collection',
            label: [
                {
                    hint: 'Field in the currently-selected table that contains a reference to a user or group that will receive an email notification',
                    label: 'Users/Groups in fields',
                    plural: 'Users/Groups in fields',
                    language: 'en',
                },
            ],
            maxLength: 5000,
        }),
        push_message_only: BooleanColumn({
            default: false,
            label: 'Push Message Only',
        }),
        category: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default:
                "javascript:gs.getProperty('glide.notification.default_category', 'c97d83137f4432005f58108c3ffa917a');",
            label: [
                {
                    hint: "The notification appears in the user notification preferences under the category provided. If no category is provided, it appears under 'Uncategorized'.",
                    label: 'Category',
                    plural: 'Categories',
                    language: 'en',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_notification_category',
        }),
        message_text: GenericColumn({
            columnType: 'email_script',
            dependent: 'collection',
            label: 'Message text',
            maxLength: 4000,
        }),
        generation_type: StringColumn({
            default: 'engine',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Action that causes an email to be sent. Specifies whether to send email based on a trigger, an event firing, or an action against a record.',
                    label: 'Send when',
                    plural: 'Send whens',
                    language: 'en',
                },
            ],
        }),
        send_self: BooleanColumn({
            default: true,
            label: 'Send to event creator',
        }),
        sys_version: StringColumn({
            default: '2',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Notification Version',
                    label: 'Sys version',
                    plural: 'Sys versions',
                    language: 'en',
                },
            ],
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        omit_watermark: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Omitting watermark prevents any email replies from updating the triggering record',
                    label: 'Omit watermark',
                    plural: 'Omit watermarks',
                    language: 'en',
                },
            ],
        }),
        action_update: BooleanColumn({
            label: [
                {
                    hint: 'Send an email whenever a record in the selected table is modified',
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        type: StringColumn({
            default: 'email',
            dropdown: 'dropdown_without_none',
            label: 'Type',
        }),
        recipient_groups: ListColumn({
            attributes: {
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'List of groups that will receive an email notification',
                    label: 'Groups',
                    plural: 'Groups',
                    language: 'en',
                },
            ],
            maxLength: 5000,
            referenceTable: 'sys_user_group',
        }),
        digest_subject: StringColumn({
            label: 'Digest Subject',
            maxLength: 100,
        }),
        digest_template: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Digest Template',
            referenceTable: 'sysevent_email_template',
            referenceQual: "javascript:'collection=NULL^ORcollection=global^ORcollection=' + current.collection",
        }),
        digest_text: GenericColumn({
            columnType: 'email_script',
            dependent: 'collection',
            label: 'Digest Text',
            maxLength: 4000,
        }),
        digest_from: StringColumn({
            label: 'Digest From',
            maxLength: 100,
        }),
        digestable: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Enables this notification to be received in a digest by users',
                    label: 'Allow Digest',
                    plural: 'Allow Digests',
                    language: 'en',
                },
            ],
        }),
        default_digest: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Send this notification in a fixed-interval digest by default for all the recipients',
                    label: 'Enable by default',
                    plural: 'Enable by defaults',
                    language: 'en',
                },
            ],
        }),
        message_html: GenericColumn({
            attributes: {
                convert_urls: false,
            },
            columnType: 'html_script',
            dependent: 'collection',
            label: 'Message HTML',
            maxLength: 4000,
        }),
        include_attachments: BooleanColumn({
            label: [
                {
                    hint: 'Send all attachments from the triggering record as email attachments',
                    label: 'Include attachments',
                    plural: 'Include attachments',
                    language: 'en',
                },
            ],
        }),
        style: ReferenceColumn({
            label: 'Stationery',
            referenceTable: 'sysevent_email_style',
        }),
        sms_alternate: GenericColumn({
            columnType: 'email_script',
            dependent: 'collection',
            label: 'SMS alternate',
            maxLength: 4000,
        }),
        content_type: StringColumn({
            default: 'text/html',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Specify whether the message is sent with a format of HTML, plain text, or both',
                    label: 'Content type',
                    plural: 'Content types',
                    language: 'en',
                },
            ],
        }),
        action_insert: BooleanColumn({
            label: [
                {
                    hint: 'Send an email whenever a new record is inserted into the selected table',
                    label: 'Inserted',
                    plural: 'Inserted',
                    language: 'en',
                },
            ],
        }),
        advanced_condition: ScriptColumn({
            dependent: 'collection',
            label: 'Advanced condition',
        }),
        recipient_users: ListColumn({
            attributes: {
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'List of users or email addresses that will receive an email notification',
                    label: 'Users',
                    plural: 'Users',
                    language: 'en',
                },
            ],
            maxLength: 5000,
            referenceTable: 'sys_user',
        }),
        mandatory: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Prevent users from unsubscribing/filtering-out this notification',
                    label: 'Mandatory',
                    plural: 'Mandatories',
                    language: 'en',
                },
            ],
        }),
        message: GenericColumn({
            columnType: 'email_script',
            dependent: 'collection',
            label: 'Message',
            maxLength: 4000,
        }),
        force_delivery: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Bypass settings that would normally prevent sending to the recipient (e.g., device.schedule, user.notification)',
                    label: 'Force delivery',
                    plural: 'Force deliveries',
                    language: 'en',
                },
            ],
        }),
        item: StringColumn({
            default: 'event.parm1',
            label: [
                {
                    hint: 'The sys_id of the subscribed item',
                    label: 'Item',
                    plural: 'Items',
                    language: 'en',
                },
            ],
        }),
        template: ReferenceColumn({
            label: 'Email template',
            referenceTable: 'sysevent_email_template',
            referenceQual: "javascript:'collection=NULL^ORcollection=global^ORcollection=' + current.collection",
        }),
        reply_to: StringColumn({
            label: [
                {
                    hint: 'Email address to be used when replying to the email notification',
                    label: 'Reply to',
                    plural: 'Reply to',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        affected_field_on_event: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'The field in the event that must be affected for this notification to send to subscribed users',
                    label: 'Affected field on event',
                    plural: 'Affected field on events',
                    language: 'en',
                },
            ],
        }),
        item_table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
            },
            label: [
                {
                    hint: 'The table that the subscribed item resides in',
                    label: 'Item table',
                    plural: 'Item tables',
                    language: 'en',
                },
            ],
            maxLength: 40,
        }),
        weight: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Used to decide which notification takes precedence when more than one qualifies',
                    label: 'Weight',
                    plural: 'Weights',
                    language: 'en',
                },
            ],
        }),
        exclude_delegates: BooleanColumn({
            default: false,
            label: [
                {
                    hint: "Do not send the notification to any delegates of this notification's recipients",
                    label: 'Exclude delegates',
                    plural: 'Exclude delegates',
                    language: 'en',
                },
            ],
        }),
        enable_dynamic_translation: BooleanColumn({
            default: false,
            label: 'Enable Dynamic Translation',
        }),
        subscribable: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Allow users to choose this notification when subscribing to their messages',
                    label: 'Subscribable',
                    plural: 'Subscribables',
                    language: 'en',
                },
            ],
        }),
        condition: ConditionsColumn({
            attributes: {
                extended_operators: 'VALCHANGES;CHANGESFROM;CHANGESTO',
            },
            dependent: 'collection',
            label: [
                {
                    hint: 'Send Notification when conditions evaluate to true',
                    label: 'Conditions',
                    plural: 'Conditions',
                    language: 'en',
                },
            ],
            maxLength: 8000,
        }),
        event_parm_2: BooleanColumn({
            label: [
                {
                    hint: 'The second event parameter contains a recipient, either a user sys_id, group sys_id or an email address, who should receive this notification',
                    label: 'Event parm 2 contains recipient',
                    plural: 'Event parm 2 contains recipients',
                    language: 'en',
                },
            ],
        }),
        digest_separator_text: GenericColumn({
            columnType: 'email_script',
            default: '\\n--------------------------------------------------------------------------------\\n',
            dependent: 'collection',
            label: 'Digest Separator (text)',
            maxLength: 4000,
        }),
        digest_type: StringColumn({
            default: 'single',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: "'Multiple target' type digest lets you collates updates for this notification from multiple records instead of a single record",
                    label: 'Digest type',
                    plural: 'Digest types',
                    language: 'en',
                },
            ],
        }),
        digest_reply_to: StringColumn({
            label: 'Digest Reply To',
            maxLength: 100,
        }),
        digest_separator_html: GenericColumn({
            columnType: 'html_script',
            default: '<br><hr><br>',
            dependent: 'collection',
            label: 'Digest Separator (HTML)',
            maxLength: 4000,
        }),
        default_interval: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Set the interval at which the digest is triggered for this notification',
                    label: 'Default Interval',
                    plural: 'Default Intervals',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_email_digest_interval',
            referenceQual: 'active=true',
        }),
        digest_html: GenericColumn({
            attributes: {
                convert_urls: false,
            },
            columnType: 'html_script',
            dependent: 'collection',
            label: 'Digest HTML',
            maxLength: 4000,
        }),
        message_list: ListColumn({
            attributes: {
                array: 'denormalized',
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Push Messages',
            maxLength: 1024,
            referenceTable: 'sys_push_notif_msg',
            referenceQual: "javascript:(current.collection) ? 'table=' + current.collection : 'table=NULL'",
        }),
    },
    textIndex: true,
})
